      },
      "verifier": {
        "type": "string",
        "minLength": 1,
        "description": "The verifier's brief: one check per expect line, in order, each saying what to run and what PASS and FAIL look like. It is fixed when you return and becomes the Task part of the verifier's prompt, word for word."
      }
    }
  },
